import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.ArrayList;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));int n = Integer.parseInt(br.readLine().trim());if (n == 0) {System.out.println(0);return;}ArrayList<ArrayList<Integer>> adj = new ArrayList<ArrayList<Integer>>(n + 1);for (int i = 0; i <= n; i++) {adj.add(new ArrayList<Integer>());}for (int i = 0; i < n - 1; i++) {StringTokenizer st = new StringTokenizer(br.readLine());int u = Integer.parseInt(st.nextToken());int v = Integer.parseInt(st.nextToken());adj.get(u).add(v);adj.get(v).add(u);}int[] blocked = new int[n + 1];StringTokenizer st = new StringTokenizer(br.readLine());for (int i = 1; i <= n; i++) {blocked[i] = Integer.parseInt(st.nextToken());}boolean[] visited = new boolean[n + 1];int maxCities = 0;for (int i = 1; i <= n; i++) {if (blocked[i] == 0 && !visited[i]) {int count = 0;java.util.Queue<Integer> q = new java.util.LinkedList<Integer>();q.add(i);visited[i] = true;while (!q.isEmpty()) {int curr = q.poll();count++;for (int neighbor : adj.get(curr)) {if (blocked[neighbor] == 0 && !visited[neighbor]) {visited[neighbor] = true;q.add(neighbor);}}}if (count > maxCities) {maxCities = count;}}}System.out.println(maxCities);}}